-- (mmarznvndvbwyhhtbfjy).
-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000038_launch_hardening.sql .. 20261012000038_launch_hardening.sql;
-- do not edit by hand.
begin;

-- Run the trader sign-up script (docs/launch/trader-sign-up-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000037') then
    raise exception 'Run the trader sign-up script (docs/launch/trader-sign-up-production.sql) first: migration 20261012000037 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000038_launch_hardening.sql
-- Launch hardening, from the baseline security audit (October 2026).
--  1. A general rate limiter (public.rate_allow) for the endpoints that had none: the phone-number redirect, the
--     search beacon, the pre-launch lock page and the admin sign-in.
--  2. public.lock_grant_valid: the pre-launch lock lets in someone holding a shared link only once the link is real.
--  3. The admin needs two-step sign-in: is_admin() is true only for a session that has passed its authenticator code
--     (aal2). A stolen password alone no longer reaches the admin functions.
--  4. The email-code gate runs its limits before anything else and no longer tells a script which address is the
--     admin's (the app answers that one as if a code had gone).
--  5. A trader's private records (job requests, quotes and invoices, bank details, alert settings, sent messages) go
--     when the trader stops being the listing's owner: unlinked, re-invited, or their account deleted. The next
--     account linked to the listing starts clean.
--  6. Approving a sign-up request applies the same account checks as a trader link.
--  7. Emails to customers are capped per listing (30 a day), and a quote can't be accepted after its "valid until".
--  8. New functions are no longer executable by everyone by default (the 000003 revoke was scoped to a schema,
--     which Postgres ignores for the built-in grant).

-- ---------------------------------------------------------------- 1. rate limiter
create table if not exists public.rate_events (
  bucket text not null,
  key text not null,
  at timestamptz not null default now()
);
create index if not exists rate_events_bucket_key_at on public.rate_events (bucket, key, at);
alter table public.rate_events enable row level security;
revoke all on public.rate_events from public, anon, authenticated;

-- Records one event for (bucket, key) and says whether it's within p_limit events per p_window. Old events are
-- tidied as it goes. Server only.
create or replace function public.rate_allow(p_bucket text, p_key text, p_limit int, p_window interval)
returns boolean
language plpgsql security definer set search_path = ''
as $$
declare
  v_n int;
begin
  if p_bucket is null or p_key is null or p_key = '' or p_limit is null or p_limit < 1 or p_window is null then
    raise exception 'bad_rate_limit';
  end if;
  perform pg_advisory_xact_lock(hashtext('rate:' || p_bucket || ':' || p_key));
  delete from public.rate_events where bucket = p_bucket and key = p_key and at <= now() - p_window;
  if random() < 0.01 then
    delete from public.rate_events where at < now() - interval '2 days';
  end if;
  select count(*) into v_n from public.rate_events where bucket = p_bucket and key = p_key;
  if v_n >= p_limit then
    return false;
  end if;
  insert into public.rate_events (bucket, key) values (p_bucket, p_key);
  return true;
end;
$$;
revoke execute on function public.rate_allow(text, text, int, interval) from public, anon, authenticated;
grant execute on function public.rate_allow(text, text, int, interval) to service_role;

-- For limits on failures only (wrong passwords, wrong codes): rate_failures counts, rate_fail records one.
create or replace function public.rate_failures(p_bucket text, p_key text, p_window interval) returns int
language sql stable security definer set search_path = ''
as $$
  select count(*)::int from public.rate_events where bucket = p_bucket and key = p_key and at > now() - p_window;
$$;
create or replace function public.rate_fail(p_bucket text, p_key text) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if p_bucket is null or p_key is null or p_key = '' then
    raise exception 'bad_rate_limit';
  end if;
  delete from public.rate_events where bucket = p_bucket and key = p_key and at < now() - interval '1 day';
  insert into public.rate_events (bucket, key) values (p_bucket, p_key);
end;
$$;
revoke execute on function public.rate_failures(text, text, interval) from public, anon, authenticated;
revoke execute on function public.rate_fail(text, text) from public, anon, authenticated;
grant execute on function public.rate_failures(text, text, interval) to service_role;
grant execute on function public.rate_fail(text, text) to service_role;

-- ---------------------------------------------------------------- 2. pre-launch lock: is the shared link real?
create or replace function public.lock_grant_valid(p_kind text, p_key text) returns boolean
language plpgsql stable security definer set search_path = ''
as $$
begin
  if p_kind = 'review' then
    return exists (select 1 from public.providers where slug = p_key and status = 'live');
  end if;
  if p_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  if p_kind = 'doc' then
    return exists (select 1 from public.trade_docs where token = p_key::uuid and status <> 'draft');
  elsif p_kind = 'consent' then
    return exists (select 1 from public.providers where consent_token = p_key::uuid and consent_token_used_at is null
                   and status = 'invited' and consent_token_expires_at > now());
  elsif p_kind = 'link' then
    return exists (select 1 from public.trader_link_tokens where token_hash = private.trader_link_hash(p_key::uuid)
                   and used_at is null and revoked_at is null and expires_at > now());
  end if;
  return false;
end;
$$;
revoke execute on function public.lock_grant_valid(text, text) from public, anon, authenticated;
grant execute on function public.lock_grant_valid(text, text) to service_role;

-- ---------------------------------------------------------------- 3. admin needs two-step sign-in
create or replace function public.is_admin() returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(auth.jwt() ->> 'aal', '') = 'aal2' and coalesce(
    (select p.role = 'admin' from public.profiles p where p.user_id = auth.uid()),
    false
  );
$$;

-- Whether the signed-in account is the admin's, before its second step: the admin pages use it to send the admin
-- to the authenticator step instead of the login page. Says nothing about anyone else's account.
create or replace function public.am_i_admin_account() returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select p.role = 'admin' from public.profiles p where p.user_id = auth.uid()), false);
$$;
revoke execute on function public.am_i_admin_account() from public, anon;
grant execute on function public.am_i_admin_account() to authenticated;

-- ---------------------------------------------------------------- 4. email gate: limits first
create or replace function public.email_gate(p_email text, p_ip_hash text)
returns table (request_id bigint, verdict text)
language plpgsql security definer set search_path = ''
as $$
declare
  v_norm text := private.normalise_email(p_email);
  v_typed text := lower(btrim(coalesce(p_email, '')));
  v_ip text := coalesce(p_ip_hash, '');
  v_limits jsonb;
  v_day_start timestamptz;
  v_month_start timestamptz;
  v_a15 int;
  v_a24 int;
  v_i1 int;
  v_i24 int;
  v_day int;
  v_month int;
  v_outcome text := 'pending';
  v_verdict text := 'ok';
  v_id bigint;
begin
  -- Address lock first, then the site-wide one (the caps), always in that order.
  perform pg_advisory_xact_lock(hashtext('email_gate:' || coalesce(v_norm, '')));
  perform pg_advisory_xact_lock(hashtext('email_gate:cap'));

  -- At most once an hour, whoever asks first tidies old sign-in records and unused accounts.
  update private.housekeeping set last_run = now()
  where job = 'tidy_sign_in_records' and last_run < now() - interval '1 hour';
  if found then
    perform private.tidy_sign_in_records();
  end if;
  delete from public.email_requests where created_at < now() - interval '30 days';

  select value into v_limits from public.settings where key = 'email_limits';
  v_limits := coalesce(v_limits, '{}'::jsonb);

  select count(*) filter (where created_at > now() - interval '15 minutes'),
         count(*) filter (where created_at > now() - interval '24 hours')
    into v_a15, v_a24
  from public.email_requests where v_norm is not null and email_norm = v_norm;
  select count(*) filter (where created_at > now() - interval '1 hour'),
         count(*) filter (where created_at > now() - interval '24 hours')
    into v_i1, v_i24
  from public.email_requests where ip_hash = v_ip;

  -- Today and this calendar month in Bolton; only 'sent' rows used up Resend's allowance.
  v_day_start := date_trunc('day', now() at time zone 'Europe/London') at time zone 'Europe/London';
  v_month_start := date_trunc('month', now() at time zone 'Europe/London') at time zone 'Europe/London';
  select count(*) filter (where created_at >= v_day_start), count(*)
    into v_day, v_month
  from public.email_requests where outcome = 'sent' and created_at >= v_month_start;

  if v_norm is null then
    v_outcome := 'invalid';
    v_verdict := 'invalid';
  elsif v_a15 >= coalesce((v_limits ->> 'address_15m')::int, 3) or v_a24 >= coalesce((v_limits ->> 'address_24h')::int, 6) then
    v_outcome := 'limited_address';
    v_verdict := 'address_limited';
  elsif v_i1 >= coalesce((v_limits ->> 'ip_1h')::int, 10) or v_i24 >= coalesce((v_limits ->> 'ip_24h')::int, 20) then
    v_outcome := 'limited_ip';
    v_verdict := 'ip_limited';
  elsif private.is_admin_email(v_typed) or exists (
    select 1 from public.settings s, jsonb_array_elements_text(s.value) e
    where s.key = 'admin_emails' and jsonb_typeof(s.value) = 'array' and private.normalise_email(e) = v_norm
  ) then
    v_outcome := 'admin_address';
    v_verdict := 'admin_address';
  elsif private.email_domain_blocked(v_typed) then
    v_outcome := 'blocked_domain';
    v_verdict := 'blocked_domain';
  elsif exists (
    select 1 from auth.users u
    where u.deleted_at is null and coalesce(u.email, '') <> ''
      and private.normalise_email(u.email) = v_norm and lower(u.email) <> v_typed
      and not private.abandoned_email_account(u.id)
  ) then
    v_outcome := 'address_taken';
    v_verdict := 'address_taken';
  elsif v_day >= coalesce((v_limits ->> 'daily_cap')::int, 80) or v_month >= coalesce((v_limits ->> 'monthly_cap')::int, 2900) then
    v_outcome := 'cap_reached';
    v_verdict := 'cap_reached';
  end if;

  insert into public.email_requests (email_norm, ip_hash, outcome) values (coalesce(v_norm, ''), v_ip, v_outcome)
  returning id into v_id;
  return query select v_id, v_verdict;
end;
$$;
revoke execute on function public.email_gate(text, text) from public, anon, authenticated;
grant execute on function public.email_gate(text, text) to service_role;

-- ---------------------------------------------------------------- 5. a trader's private records go with them
create or replace function private.forget_trader_data(p_provider uuid) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  delete from public.trade_docs where provider_id = p_provider;
  delete from public.job_requests where provider_id = p_provider;
  delete from public.trader_billing where provider_id = p_provider;
  delete from public.trader_alert_settings where provider_id = p_provider;
  delete from public.notifications where provider_id = p_provider;
end;
$$;
revoke execute on function private.forget_trader_data(uuid) from public, anon, authenticated;

create or replace function public.delete_my_account() returns text[]
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_phone text;
  v_slugs text[];
  c_reason constant text := 'Reviewer deleted their account';
  c_author constant text := 'Author deleted their account';
begin
  if v_uid is null then
    raise exception 'not_member';
  end if;
  if exists (select 1 from public.profiles where user_id = v_uid and role = 'admin') then
    raise exception 'admin_account';
  end if;

  delete from public.phone_retention where purge_after < now();
  delete from public.identity_retention where purge_after < now();

  select nullif(btrim(u.phone), '') into v_phone from auth.users u where u.id = v_uid;
  if v_phone is not null and not exists (select 1 from public.phone_retention r where r.user_id = v_uid) then
    insert into public.phone_retention (user_id, phone_e164) values (v_uid, '+' || ltrim(v_phone, '+'));
  end if;
  -- The hashed sign-in keys, while the account still has them (GoTrue's soft delete obfuscates them next).
  insert into public.identity_retention (user_id, identity_key)
  select v_uid, k from unnest(private.identity_keys(v_uid)) k
  where not exists (select 1 from public.identity_retention ir where ir.user_id = v_uid and ir.identity_key = k);

  -- A trader leaving takes their customers' details with them: the next account linked to the listing starts clean.
  perform private.forget_trader_data(p.id) from public.providers p where p.user_id = v_uid;

  -- Their community questions and answers come down too (the public views hide a deleted account's anyway).
  update public.questions set status = 'removed', removal_reason = c_author
  where asker_id = v_uid and status <> 'removed';
  update public.question_answers set status = 'removed', removal_reason = c_author
  where author_id = v_uid and status <> 'removed';

  with taken_down as (
    update public.reviews r set status = 'removed', removal_reason = c_reason
    where r.reviewer_id = v_uid and r.status <> 'removed'
    returning r.provider_id
  ), replies as (
    update public.review_responses rr set status = 'removed', removal_reason = c_reason
    where rr.author_id = v_uid and rr.status <> 'removed'
    returning rr.provider_id
  ), unlinked as (
    update public.providers p set user_id = null
    where p.user_id = v_uid
    returning p.id
  )
  select coalesce(array_agg(distinct p.slug order by p.slug), '{}') into v_slugs
  from public.providers p
  where p.id in (select provider_id from taken_down union select provider_id from replies union select id from unlinked);

  update public.profiles set deleted_at = coalesce(deleted_at, now()), display_name = null where user_id = v_uid;

  if not exists (select 1 from public.audit_log a where a.actor_id = v_uid and a.action = 'delete_account') then
    insert into public.audit_log (actor_id, action, target_type, target_id) values (v_uid, 'delete_account', 'user', v_uid::text);
  end if;

  return v_slugs;
end;
$$;

create or replace function public.admin_unlink_provider(p_provider uuid, p_reason text) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_user uuid;
begin
  if not public.is_admin() then
    raise exception 'not admin' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'reason is required' using errcode = 'check_violation';
  end if;
  select user_id into v_user from public.providers where id = p_provider for update;
  if not found then
    raise exception 'provider not found' using errcode = 'P0002';
  end if;
  if v_user is null then
    raise exception 'provider not linked' using errcode = 'check_violation';
  end if;
  update public.providers set user_id = null where id = p_provider;
  -- Whoever is linked next must not see this account's customers or bank details.
  perform private.forget_trader_data(p_provider);
  -- An account left with no listing goes back to being a resident.
  if not exists (select 1 from public.providers where user_id = v_user) then
    update public.profiles set role = 'resident' where user_id = v_user and role = 'provider';
  end if;
  insert into public.audit_log (actor_id, action, target_type, target_id, reason)
  values (auth.uid(), 'unlink_provider', 'provider', p_provider::text, btrim(p_reason));
end;
$$;

create or replace function public.admin_reinvite_provider(p_id uuid, p_reason text) returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_status public.provider_status;
  v_token uuid;
begin
  if not public.is_admin() then
    raise exception 'not admin' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'a reason is required to re-invite a provider' using errcode = 'check_violation';
  end if;
  select status into v_status from public.providers where id = p_id for update;
  if not found then
    raise exception 'provider not found' using errcode = 'P0002';
  end if;
  if v_status <> 'removed' then
    raise exception 'only a removed provider can be re-invited' using errcode = 'check_violation';
  end if;
  update public.providers
  set status = 'invited',
      consent_at = null,
      consent_evidence = null,
      user_id = null,
      consent_token = gen_random_uuid(),
      consent_token_used_at = null,
      consent_token_expires_at = now() + interval '14 days'
  where id = p_id
  returning consent_token into v_token;
  perform private.forget_trader_data(p_id);
  insert into public.audit_log (actor_id, action, target_type, target_id, reason)
  values (auth.uid(), 'reinvite_provider', 'provider', p_id::text, btrim(p_reason));
  return v_token;
end;
$$;

-- ---------------------------------------------------------------- 6. approving a sign-up request
create or replace function public.admin_approve_listing_request(p_id uuid, p_provider uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  r public.listing_requests;
  v_owner uuid;
  v_status public.provider_status;
  v_slug text;
  v_business text;
  v_email text;
begin
  if not public.is_admin() then
    raise exception 'not admin' using errcode = '42501';
  end if;
  select * into r from public.listing_requests where id = p_id for update;
  if not found then
    raise exception 'listing request not found' using errcode = 'P0002';
  end if;
  if r.user_id is null then
    raise exception 'no_account';
  end if;
  select user_id, status, slug, business_name into v_owner, v_status, v_slug, v_business
  from public.providers where id = p_provider for update;
  if not found then
    raise exception 'provider not found' using errcode = 'P0002';
  end if;
  if v_status not in ('consented', 'live', 'paused') then
    raise exception 'not_agreed';
  end if;
  if v_owner is not null and v_owner <> r.user_id then
    raise exception 'already_linked';
  end if;
  select email into v_email from auth.users where id = r.user_id and deleted_at is null;
  if not found or not exists (select 1 from public.profiles where user_id = r.user_id and deleted_at is null) then
    raise exception 'account_gone';
  end if;
  -- The same account checks as a trader link (private.trader_link_state): a normal sign-in, not blocked, not the
  -- admin, and not already running another listing.
  if coalesce(private.sign_in_kind(r.user_id), '') not in ('google', 'email', 'phone')
     or exists (select 1 from public.profiles where user_id = r.user_id and (blocked_at is not null or role = 'admin')) then
    raise exception 'account_not_allowed';
  end if;
  if exists (select 1 from public.providers p where p.user_id = r.user_id and p.id <> p_provider and p.status <> 'removed') then
    raise exception 'account_already_linked';
  end if;

  update public.providers set user_id = r.user_id where id = p_provider;
  update public.profiles set role = 'provider' where user_id = r.user_id and role = 'resident';
  update public.listing_requests set status = 'done', handled_at = now() where id = p_id;
  insert into public.audit_log (actor_id, action, target_type, target_id, reason)
  values (auth.uid(), 'approve_listing_request', 'provider', p_provider::text, p_id::text);
  return jsonb_build_object('email', v_email, 'contact_name', r.contact_name, 'business_name', v_business,
                            'slug', v_slug, 'plan', r.plan);
end;
$$;
revoke execute on function public.admin_approve_listing_request(uuid, uuid) from public, anon;
grant execute on function public.admin_approve_listing_request(uuid, uuid) to authenticated;

-- ---------------------------------------------------------------- 7. customer emails and quote expiry
-- The customer accepts or declines a sent quote. Returns {result: 'ok' | 'already' | 'expired' | 'unavailable',
-- status}. A quote past its "valid until" date can still be declined, not accepted.
create or replace function public.answer_quote(p_token uuid, p_accept boolean) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
begin
  select * into v from public.trade_docs where token = p_token and kind = 'quote' for update;
  if v.id is null or v.status = 'draft' then
    return jsonb_build_object('result', 'unavailable');
  end if;
  if v.status <> 'sent' then
    return jsonb_build_object('result', 'already', 'status', v.status);
  end if;
  if p_accept and v.until is not null and v.until < private.london_today() then
    return jsonb_build_object('result', 'expired', 'until', v.until);
  end if;
  update public.trade_docs
  set status = case when p_accept then 'accepted' else 'declined' end, answered_at = now(), updated_at = now()
  where id = v.id;
  return jsonb_build_object('result', 'ok', 'status', case when p_accept then 'accepted' else 'declined' end,
                            'id', v.id);
end;
$$;
revoke execute on function public.answer_quote(uuid, boolean) from public, anon, authenticated;
grant execute on function public.answer_quote(uuid, boolean) to service_role;

-- Claims a message to the customer on a quote or invoice (as 000036), now with a daily email cap per listing.
create or replace function private.claim_customer_message(p_kind text, p_doc uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
  v_out jsonb := '[]'::jsonb;
  v_ch text;
  v_to text;
  v_id uuid;
begin
  select * into v from public.trade_docs where id = p_doc;
  if v.id is null then
    return null;
  end if;
  if p_kind = 'review_request' and not (v.kind = 'invoice' and v.status = 'paid' and v.ask_review) then
    return null;
  end if;
  if p_kind like 'payment_reminder_%' and not (v.kind = 'invoice' and v.status = 'unpaid') then
    return null;
  end if;
  if p_kind = 'doc_email' and v.status = 'draft' then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtext('claim_alerts:' || v.provider_id::text));
  foreach v_ch in array array['sms', 'email'] loop
    v_to := case v_ch when 'sms' then case when v.customer_phone ~ '^\+447' then v.customer_phone end
                      else v.customer_email end;
    continue when v_to is null or (p_kind = 'doc_email' and v_ch = 'sms');
    continue when v_ch = 'sms' and (select count(*) from public.notifications n
                   where n.provider_id = v.provider_id and n.channel = 'sms'
                     and n.kind in ('review_request', 'payment_reminder_1', 'payment_reminder_2')
                     and n.created_at > now() - interval '24 hours') >= 20;
    -- And at most 30 emails to customers a day per listing: "Email it" can't be looped to spam strangers or to use
    -- up the sending allowance that residents' sign-in codes depend on.
    continue when v_ch = 'email' and (select count(*) from public.notifications n
                   where n.provider_id = v.provider_id and n.channel = 'email'
                     and n.kind in ('review_request', 'payment_reminder_1', 'payment_reminder_2', 'doc_email')
                     and n.created_at > now() - interval '24 hours') >= 30;
    continue when p_kind = 'review_request' and exists (
      select 1 from public.notifications n
      where n.provider_id = v.provider_id and n.kind = 'review_request' and n.to_addr = v_to
        and n.created_at > now() - interval '90 days');
    insert into public.notifications (provider_id, kind, ref_id, channel, to_addr)
    values (v.provider_id, p_kind, v.id, v_ch, v_to)
    on conflict (kind, ref_id, provider_id, channel) do nothing
    returning id into v_id;
    if v_id is not null then
      v_out := v_out || jsonb_build_array(jsonb_build_object('id', v_id, 'provider_id', v.provider_id, 'channel', v_ch, 'to', v_to));
    end if;
    v_id := null;
  end loop;
  return jsonb_build_object('doc', private.doc_json(v),
                            'business_name', (select business_name from public.providers where id = v.provider_id),
                            'slug', (select slug from public.providers where id = v.provider_id and status = 'live'),
                            'send', v_out);
end;
$$;
revoke execute on function private.claim_customer_message(text, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------- 8. new functions closed by default
-- 000003 revoked the default EXECUTE "in schema public", which doesn't touch Postgres's built-in grant to PUBLIC.
-- Without the schema it does: functions created from now on are callable only by those granted. (Every existing
-- function already revokes and grants explicitly; supabase/tests/function_grants.test.sql checks it stays that way.)
alter default privileges revoke execute on functions from public;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000038', 'launch_hardening') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
declare
  f text;
begin
  if to_regclass('public.rate_events') is null then
    raise exception 'Launch hardening check failed: public.rate_events is missing';
  end if;
  foreach f in array array['rate_allow', 'rate_failures', 'rate_fail', 'lock_grant_valid', 'am_i_admin_account'] loop
    if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                   where n.nspname = 'public' and p.proname = f) then
      raise exception 'Launch hardening check failed: function public.% is missing', f;
    end if;
  end loop;
  if has_function_privilege('anon', 'public.rate_allow(text, text, int, interval)', 'execute')
     or has_function_privilege('authenticated', 'public.lock_grant_valid(text, text)', 'execute') then
    raise exception 'Launch hardening check failed: a server-only function is open';
  end if;
  if (select prosrc from pg_proc where oid = 'public.is_admin()'::regprocedure) not like '%aal2%' then
    raise exception 'Launch hardening check failed: is_admin() does not need the authenticator code';
  end if;
  if exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace
             and has_function_privilege('anon', p.oid, 'execute')
             and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')) then
    raise exception 'Launch hardening check failed: a database function is callable without signing in';
  end if;
end
$verify$;

commit;

select 'Launch hardening database changes applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000038')) as migrations_recorded;
